__aicore__ inline KernelMean() {}
__aicore__ inline void Init(__gm__ uint8_t *srcGm, __gm__ uint8_t *dstGm, uint32_t outter, uint32_t
inner, uint32_t n, uint32_t Size)
{
meanParams.outter = outter;
meanParams.inner = inner;
meanParams.n = n;
tmpSize = Size;
srcGlobal.SetGlobalBuffer((__gm__ T *)srcGm);
dstGlobal.SetGlobalBuffer((__gm__ T *)dstGm);
pipe.InitBuffer(inQueueX, 1, meanParams.outter * meanParams.inner * sizeof(T));
pipe.InitBuffer(outQueueY , 1, (meanParams.outter * sizeof(T) + AscendC::ONE_BLK_SIZE - 1) /
AscendC::ONE_BLK_SIZE * AscendC::ONE_BLK_SIZE);
